#!/usr/bin/env bash
#
# Chemical Playground — server provisioning (runs ON the server, as root).
#
# This file is uploaded and executed by scripts/setup-server.sh. It is kept
# separate so the local orchestrator can call it in phases:
#
#   --phase provision   install packages, users, docker, nginx, firewall, app unit
#   --phase harden      key-only SSH + AllowUsers (called only after key login is verified)
#   --phase tls         issue/renew the certificate and switch nginx to HTTPS
#
# The config file is a root-readable shell fragment generated by the local
# script. It never contains the SSH password or private keys. A Cloudflare API
# token, when used, is passed in a separate 0600 file and moved to
# /etc/letsencrypt/cloudflare.ini.
#
set -euo pipefail
umask 022

PHASE="provision"
CONFIG=""

usage() {
    cat <<'EOF'
Usage: setup-server-remote.sh --config FILE [--phase provision|harden|tls]

This script is intended to be uploaded and run by scripts/setup-server.sh.
EOF
}

while [ "$#" -gt 0 ]; do
    case "$1" in
        --config)
            CONFIG="${2:-}"
            shift 2
            ;;
        --phase)
            PHASE="${2:-}"
            shift 2
            ;;
        -h|--help)
            usage
            exit 0
            ;;
        *)
            echo "unknown argument: $1" >&2
            usage >&2
            exit 2
            ;;
    esac
done

log()  { printf '\n\033[1;32m[chemical-setup]\033[0m %s\n' "$*"; }
warn() { printf '\n\033[1;33m[chemical-setup] warning:\033[0m %s\n' "$*" >&2; }
die()  { printf '\n\033[1;31m[chemical-setup] error:\033[0m %s\n' "$*" >&2; exit 1; }

[ "$(id -u)" -eq 0 ] || die "this script must run as root (use sudo)"
[ -n "$CONFIG" ] || die "--config is required"
[ -f "$CONFIG" ] || die "config file not found: $CONFIG"
case "$(stat -c '%a' "$CONFIG")" in
    600|400) ;;
    *) die "config file must be mode 600 or 400 (got $(stat -c '%a' "$CONFIG"))" ;;
esac

# shellcheck disable=SC1090
source "$CONFIG"

: "${ADMIN_USER:=admin}"
: "${OPS_PUBKEY:=}"
: "${DEPLOY_PUBKEY:=}"
: "${APP_DIR:=/home/playground/app}"
: "${DOMAIN:=chemicallang.com www.chemicallang.com}"
: "${EMAIL:=}"
: "${TLS_MODE:=none}"
: "${SSH_PORT:=22}"
: "${IMAGE_TAGS:=v0.5.11-ubuntu v0.5.10-ubuntu v0.5.9-ubuntu}"
: "${SKIP_IMAGES:=0}"
: "${CF_CREDENTIALS_FILE:=/tmp/chemical-cloudflare.ini}"

[ "$APP_DIR" = "/home/playground/app" ] || die "APP_DIR must be /home/playground/app (the playground binary hardcodes this path)"
[[ "$ADMIN_USER" =~ ^[a-z_][a-z0-9_-]*$ ]] || die "invalid ADMIN_USER"
[ "$ADMIN_USER" != "root" ] || die "ADMIN_USER must not be root"
[[ "$SSH_PORT" =~ ^[0-9]+$ ]] || die "invalid SSH_PORT"
[ -n "$OPS_PUBKEY" ] || die "OPS_PUBKEY is empty"
[ -n "$DEPLOY_PUBKEY" ] || die "DEPLOY_PUBKEY is empty"

APEX="${DOMAIN%% *}"
[ -n "$APEX" ] || die "DOMAIN is empty"
SSL_CERT="/etc/letsencrypt/live/${APEX}/fullchain.pem"
SSL_KEY="/etc/letsencrypt/live/${APEX}/privkey.pem"

cleanup_tmp() {
    rm -f "$CONFIG"
    rm -f "$CF_CREDENTIALS_FILE"
    rm -f "$0"
}
trap cleanup_tmp EXIT

# ---------------------------------------------------------------------------
# helpers
# ---------------------------------------------------------------------------

ensure_app_user() {
    local uid1000_user app_uid app_gid app_group
    uid1000_user="$(getent passwd 1000 | cut -d: -f1 || true)"

    if [ -n "${APP_USER:-}" ]; then
        id -u "$APP_USER" >/dev/null 2>&1 || die "APP_USER '$APP_USER' does not exist"
    elif [ -n "$uid1000_user" ]; then
        APP_USER="$uid1000_user"
        warn "uid 1000 is already used by '$APP_USER'; using it as the playground service account (no separate playground uid is possible without breaking the binary's hardcoded 1000:1000)"
    else
        if getent group 1000 >/dev/null 2>&1; then
            useradd --uid 1000 --gid 1000 --create-home --home-dir /home/playground --shell /usr/sbin/nologin playground
        else
            groupadd --gid 1000 playground
            useradd --uid 1000 --gid 1000 --create-home --home-dir /home/playground --shell /usr/sbin/nologin playground
        fi
        APP_USER="playground"
    fi

    app_uid="$(id -u "$APP_USER")"
    [ "$app_uid" -eq 1000 ] || die "the playground binary requires uid 1000, but '$APP_USER' has uid $app_uid"

    if getent group 1000 >/dev/null 2>&1; then
        app_group="$(getent group 1000 | cut -d: -f1)"
    else
        groupadd --gid 1000 playground
        app_group="playground"
    fi
    app_gid="$(getent group "$app_group" | cut -d: -f3)"

    APP_GROUP="$app_group"
    APP_GID="$app_gid"

    if [ "$ADMIN_USER" = "$APP_USER" ]; then
        die "ADMIN_USER '$ADMIN_USER' is also the playground service account; choose a separate --admin-user (for example --admin-user ops)"
    fi

    # The service's primary group must be 1000 so the binary's
    # `chown -R 1000:1000` on workspaces is a permitted no-op.
    usermod -aG "$APP_GROUP" "$APP_USER" 2>/dev/null || true

    install -d -o "$APP_USER" -g "$APP_GROUP" -m 0750 /home/playground
    install -d -o "$APP_USER" -g "$APP_GROUP" -m 2775 "$APP_DIR"
    chown "$APP_USER:$APP_GROUP" /home/playground "$APP_DIR"
    chmod 0750 /home/playground
    chmod 2775 "$APP_DIR"

    # The app needs docker; the deploy user deliberately does not.
    if getent group docker >/dev/null 2>&1; then
        usermod -aG docker "$APP_USER" 2>/dev/null || true
    fi
}

ensure_system_user() {
    local name="$1" home="$2" key="$3" shell="${4:-/bin/bash}"
    local actual_home

    if ! id -u "$name" >/dev/null 2>&1; then
        useradd --create-home --home-dir "$home" --shell "$shell" "$name"
    fi
    actual_home="$(getent passwd "$name" | cut -d: -f6 || true)"
    if [ -n "$actual_home" ]; then
        home="$actual_home"
    fi
    if [ "$name" != "$ADMIN_USER" ]; then
        passwd -l "$name" >/dev/null 2>&1 || true
    fi

    install -d -o "$name" -g "$(id -gn "$name")" -m 0700 "$home/.ssh"
    touch "$home/.ssh/authorized_keys"
    chown "$name:$(id -gn "$name")" "$home/.ssh/authorized_keys"
    chmod 0600 "$home/.ssh/authorized_keys"
    if ! grep -qxF "$key" "$home/.ssh/authorized_keys"; then
        printf '%s\n' "$key" >> "$home/.ssh/authorized_keys"
    fi
}

ensure_admin_user() {
    if ! id -u "$ADMIN_USER" >/dev/null 2>&1; then
        useradd --create-home --shell /bin/bash --groups sudo "$ADMIN_USER"
    else
        usermod -aG sudo "$ADMIN_USER" 2>/dev/null || true
    fi

    local home
    home="$(getent passwd "$ADMIN_USER" | cut -d: -f6)"
    [ -n "$home" ] || die "could not determine home for $ADMIN_USER"
    ensure_system_user "$ADMIN_USER" "$home" "$OPS_PUBKEY" "/bin/bash"

    install -m 0440 -o root -g root /dev/null /etc/sudoers.d/90-chemical-admin
    printf '%s ALL=(ALL) NOPASSWD:ALL\n' "$ADMIN_USER" > /etc/sudoers.d/90-chemical-admin
    visudo -cf /etc/sudoers.d/90-chemical-admin >/dev/null
}

ensure_deploy_user() {
    ensure_system_user deploy /home/deploy "$DEPLOY_PUBKEY" "/bin/bash"
    usermod -aG "$APP_GROUP" deploy 2>/dev/null || true
    if getent group systemd-journal >/dev/null 2>&1; then
        usermod -aG systemd-journal deploy 2>/dev/null || true
    fi
}

harden_app_user() {
    # Called after ensure_admin_user, so the admin account exists before the
    # service account loses sudo. This keeps a failed run recoverable.
    if [ "$ADMIN_USER" = "$APP_USER" ]; then
        die "ADMIN_USER '$ADMIN_USER' is also the playground service account; choose a separate --admin-user"
    fi

    # Cloud images commonly grant the default uid-1000 user (often 'ubuntu')
    # passwordless sudo via cloud-init. The service account must not have it.
    if id -nG "$APP_USER" 2>/dev/null | tr ' ' '\n' | grep -qx sudo; then
        gpasswd -d "$APP_USER" sudo >/dev/null 2>&1 || true
    fi

    local f
    for f in /etc/sudoers.d/*; do
        [ -f "$f" ] || continue
        case "$f" in
            /etc/sudoers.d/90-chemical-*) continue ;;
        esac
        if grep -qE "^[[:space:]]*${APP_USER}[[:space:]]" "$f" 2>/dev/null; then
            sed -i -E "/^[[:space:]]*${APP_USER}[[:space:]]/d" "$f"
            if ! visudo -cf "$f" >/dev/null 2>&1; then
                rm -f "$f"
            fi
        fi
    done

    if sudo -l -U "$APP_USER" 2>/dev/null | grep -qE 'may run|NOPASSWD|ALL'; then
        die "the playground service account '$APP_USER' still has sudo privileges; remove them and re-run"
    fi
}

write_app_scripts() {
    log "Writing service helper scripts"

    cat > /usr/local/bin/run-playground.sh <<'EOF'
#!/bin/sh
set -eu
cd /home/playground/app
exec ./playground
EOF
    chmod 0755 /usr/local/bin/run-playground.sh

    cat > /usr/local/bin/playground-cleanup <<'EOF'
#!/bin/sh
set -eu
APP_DIR=/home/playground/app

# Remove stale workspaces from crashed/timed-out requests.
if [ -d "$APP_DIR" ]; then
    find "$APP_DIR" -mindepth 1 -maxdepth 1 -type d -name 'play-*' -mmin +60 \
        -exec rm -rf {} + 2>/dev/null || true
fi

# Remove stopped sandbox containers left behind by a crash.
if command -v docker >/dev/null 2>&1; then
    docker ps -aq --filter 'name=chemical-play-' --filter 'status=exited' \
        | xargs -r docker rm -f >/dev/null 2>&1 || true
fi
EOF
    chmod 0755 /usr/local/bin/playground-cleanup

    cat > /usr/local/sbin/playground-restart <<'EOF'
#!/bin/sh
set -eu
systemctl restart playground.service
i=0
while [ "$i" -lt 40 ]; do
    if systemctl is-active --quiet playground.service \
        && curl -fsS --max-time 2 http://127.0.0.1:8080/ >/dev/null 2>&1; then
        exit 0
    fi
    i=$((i + 1))
    sleep 0.5
done
systemctl status playground.service --no-pager || true
journalctl -u playground.service -n 80 --no-pager || true
exit 1
EOF
    chmod 0755 /usr/local/sbin/playground-restart

    cat > /usr/local/bin/playground-health <<'EOF'
#!/bin/sh
set -eu
if ! curl -fsS --max-time 5 http://127.0.0.1:8080/ >/dev/null 2>&1; then
    systemctl restart playground.service
fi
EOF
    chmod 0755 /usr/local/bin/playground-health
}

write_systemd_units() {
    log "Writing systemd units"

    cat > /etc/systemd/system/playground.service <<EOF
[Unit]
Description=Chemical Playground
Documentation=https://chemicallang.com
After=network-online.target docker.service
Wants=network-online.target
Requires=docker.service
StartLimitIntervalSec=60
StartLimitBurst=5

[Service]
Type=simple
User=$APP_USER
Group=$APP_GROUP
SupplementaryGroups=docker
WorkingDirectory=$APP_DIR
Environment=PLAYGROUND_ENV=production
Environment=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
Environment=HOME=/home/playground
ExecStartPre=/usr/local/bin/playground-cleanup
ExecStart=/usr/local/bin/run-playground.sh
Restart=on-failure
RestartSec=3
TimeoutStopSec=20
KillMode=mixed
UMask=0027
LimitNOFILE=65535

# Sandbox the service. The app is an unprivileged process that talks to the
# local Docker socket; it must never be reachable from the public interface.
NoNewPrivileges=yes
PrivateTmp=yes
PrivateDevices=yes
ProtectSystem=strict
ProtectHome=read-only
ReadWritePaths=/home/playground/app /run/docker.sock /var/run/docker.sock
ProtectKernelTunables=yes
ProtectKernelModules=yes
ProtectControlGroups=yes
ProtectClock=yes
ProtectHostname=yes
RestrictSUIDSGID=yes
RestrictRealtime=yes
LockPersonality=yes
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6 AF_NETLINK
CapabilityBoundingSet=
AmbientCapabilities=
IPAddressAllow=localhost
IPAddressDeny=any

[Install]
WantedBy=multi-user.target
EOF
    chmod 0644 /etc/systemd/system/playground.service

    cat > /etc/systemd/system/playground-cleanup.service <<'EOF'
[Unit]
Description=Clean stale Chemical Playground workspaces and containers

[Service]
Type=oneshot
ExecStart=/usr/local/bin/playground-cleanup
User=root
Nice=10
EOF

    cat > /etc/systemd/system/playground-cleanup.timer <<'EOF'
[Unit]
Description=Periodic Chemical Playground cleanup

[Timer]
OnBootSec=5min
OnUnitActiveSec=15min
Persistent=true

[Install]
WantedBy=timers.target
EOF

    cat > /etc/systemd/system/playground-health.service <<'EOF'
[Unit]
Description=Chemical Playground health check

[Service]
Type=oneshot
ExecStart=/usr/local/bin/playground-health
User=root
Nice=10
EOF

    cat > /etc/systemd/system/playground-health.timer <<'EOF'
[Unit]
Description=Periodic Chemical Playground health check

[Timer]
OnBootSec=2min
OnUnitActiveSec=2min

[Install]
WantedBy=timers.target
EOF

    chmod 0644 /etc/systemd/system/playground-cleanup.service \
        /etc/systemd/system/playground-cleanup.timer \
        /etc/systemd/system/playground-health.service \
        /etc/systemd/system/playground-health.timer

    install -m 0440 -o root -g root /dev/null /etc/sudoers.d/90-chemical-deploy
    printf 'deploy ALL=(root) NOPASSWD: /usr/local/sbin/playground-restart\n' \
        > /etc/sudoers.d/90-chemical-deploy
    visudo -cf /etc/sudoers.d/90-chemical-deploy >/dev/null

    systemctl daemon-reload
    systemctl enable playground.service
    systemctl enable --now playground-cleanup.timer
}

configure_docker() {
    log "Configuring Docker"

    install -d -m 0755 /etc/docker
    if [ -f /etc/docker/daemon.json ] && ! grep -q 'chemical-playground' /etc/docker/daemon.json 2>/dev/null; then
        cp -a /etc/docker/daemon.json "/etc/docker/daemon.json.bak.$(date +%s)"
    fi
    cat > /etc/docker/daemon.json <<'EOF'
{
  "log-driver": "json-file",
  "log-opts": { "max-size": "10m", "max-file": "3" },
  "live-restore": true,
  "userland-proxy": false,
  "default-address-pools": [
    { "base": "172.30.0.0/16", "size": 24 }
  ]
}
EOF
    chmod 0644 /etc/docker/daemon.json

    systemctl enable --now docker
    systemctl restart docker

    local i
    for i in $(seq 1 30); do
        if docker info >/dev/null 2>&1; then break; fi
        sleep 1
    done
    docker info >/dev/null 2>&1 || die "Docker did not become ready"

    if getent group docker >/dev/null 2>&1; then
        usermod -aG docker "$APP_USER" 2>/dev/null || true
    fi

    if [ "$SKIP_IMAGES" != "1" ]; then
        log "Pulling playground compiler images (this can take several minutes)"
        local tag
        for tag in $IMAGE_TAGS; do
            if ! docker pull "chemicallang/chemical:$tag"; then
                warn "could not pull chemicallang/chemical:$tag (the playground will pull it on first use)"
            fi
        done
    fi
}

write_nginx_limits() {
    cat > /etc/nginx/conf.d/00-chemical-limits.conf <<'EOF'
server_tokens off;
limit_req_zone $binary_remote_addr zone=submit:10m rate=10r/m;
limit_conn_zone $binary_remote_addr zone=perip:10m;
limit_req_status 429;
limit_conn_status 429;
EOF
    chmod 0644 /etc/nginx/conf.d/00-chemical-limits.conf

    cat > /etc/nginx/snippets/chemical-proxy.conf <<'EOF'
proxy_http_version 1.1;
proxy_set_header Host $host;
proxy_set_header X-Real-IP $remote_addr;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
proxy_set_header X-Forwarded-Proto $scheme;
proxy_set_header X-Forwarded-Host $host;
proxy_set_header X-Forwarded-Port $server_port;
proxy_set_header Connection "";
proxy_connect_timeout 5s;
proxy_send_timeout 30s;
proxy_read_timeout 30s;
EOF
    chmod 0644 /etc/nginx/snippets/chemical-proxy.conf
}

write_nginx_http() {
    log "Writing nginx HTTP configuration for $DOMAIN"
    write_nginx_limits
    install -d -m 0755 /var/www/certbot

    cat > /etc/nginx/sites-available/chemicallang <<'EOF'
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name __DOMAIN__;

    access_log /var/log/nginx/chemicallang.access.log;
    error_log  /var/log/nginx/chemicallang.error.log;

    client_max_body_size 12m;
    client_body_timeout 15s;
    client_header_timeout 10s;
    send_timeout 30s;
    keepalive_timeout 65;

    location ^~ /.well-known/acme-challenge/ {
        root /var/www/certbot;
        default_type text/plain;
    }

    location = /submit {
        limit_req zone=submit burst=5 nodelay;
        limit_conn perip 10;
        proxy_pass http://127.0.0.1:8080;
        include /etc/nginx/snippets/chemical-proxy.conf;
    }

    location / {
        limit_conn perip 20;
        proxy_pass http://127.0.0.1:8080;
        include /etc/nginx/snippets/chemical-proxy.conf;
    }
}
EOF
    sed -i "s|__DOMAIN__|$DOMAIN|g" /etc/nginx/sites-available/chemicallang
    chmod 0644 /etc/nginx/sites-available/chemicallang
    ln -sfn /etc/nginx/sites-available/chemicallang /etc/nginx/sites-enabled/chemicallang
    rm -f /etc/nginx/sites-enabled/default

    nginx -t
    systemctl enable --now nginx
    systemctl reload nginx
}

write_nginx_https() {
    [ -f "$SSL_CERT" ] || die "certificate not found: $SSL_CERT"
    [ -f "$SSL_KEY" ] || die "certificate key not found: $SSL_KEY"
    log "Writing nginx HTTPS configuration for $DOMAIN"
    write_nginx_limits

    cat > /etc/nginx/sites-available/chemicallang <<'EOF'
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name __DOMAIN__;

    location ^~ /.well-known/acme-challenge/ {
        root /var/www/certbot;
        default_type text/plain;
    }

    location / {
        return 301 https://$host$request_uri;
    }
}

server {
    listen 443 ssl http2 default_server;
    listen [::]:443 ssl http2 default_server;
    server_name __DOMAIN__;

    access_log /var/log/nginx/chemicallang.access.log;
    error_log  /var/log/nginx/chemicallang.error.log;

    ssl_certificate     __SSL_CERT__;
    ssl_certificate_key __SSL_KEY__;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers off;
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 1d;
    ssl_session_tickets off;

    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;
    add_header X-Frame-Options SAMEORIGIN always;
    add_header X-Content-Type-Options nosniff always;
    add_header Referrer-Policy no-referrer-when-downgrade always;
    add_header Permissions-Policy "geolocation=(), microphone=(), camera=()" always;

    client_max_body_size 12m;
    client_body_timeout 15s;
    client_header_timeout 10s;
    send_timeout 30s;
    keepalive_timeout 65;

    location ^~ /.well-known/acme-challenge/ {
        root /var/www/certbot;
        default_type text/plain;
    }

    location = /submit {
        limit_req zone=submit burst=5 nodelay;
        limit_conn perip 10;
        proxy_pass http://127.0.0.1:8080;
        include /etc/nginx/snippets/chemical-proxy.conf;
    }

    location / {
        limit_conn perip 20;
        proxy_pass http://127.0.0.1:8080;
        include /etc/nginx/snippets/chemical-proxy.conf;
    }
}
EOF
    sed -i \
        -e "s|__DOMAIN__|$DOMAIN|g" \
        -e "s|__SSL_CERT__|$SSL_CERT|g" \
        -e "s|__SSL_KEY__|$SSL_KEY|g" \
        /etc/nginx/sites-available/chemicallang
    chmod 0644 /etc/nginx/sites-available/chemicallang
    ln -sfn /etc/nginx/sites-available/chemicallang /etc/nginx/sites-enabled/chemicallang
    rm -f /etc/nginx/sites-enabled/default

    install -d -m 0755 /etc/letsencrypt/renewal-hooks/deploy
    cat > /etc/letsencrypt/renewal-hooks/deploy/reload-nginx.sh <<'EOF'
#!/bin/sh
set -eu
systemctl reload nginx
EOF
    chmod 0755 /etc/letsencrypt/renewal-hooks/deploy/reload-nginx.sh

    nginx -t
    systemctl reload nginx
}

issue_certificate() {
    if [ -f "$SSL_CERT" ] && [ -f "$SSL_KEY" ]; then
        log "Certificate for $APEX already exists; installing HTTPS configuration"
        write_nginx_https
        return 0
    fi

    case "$TLS_MODE" in
        none)
            log "TLS mode is 'none'; leaving nginx on HTTP until a certificate is issued"
            return 0
            ;;
        cloudflare)
            log "Issuing Let's Encrypt certificate via Cloudflare DNS-01"
            apt-get -y -o Dpkg::Options::=--force-confold install python3-certbot-dns-cloudflare
            [ -f "$CF_CREDENTIALS_FILE" ] || die "Cloudflare credentials file not found: $CF_CREDENTIALS_FILE"
            install -d -m 0700 /etc/letsencrypt
            install -m 0600 -o root -g root "$CF_CREDENTIALS_FILE" /etc/letsencrypt/cloudflare.ini
            rm -f "$CF_CREDENTIALS_FILE"
            ;;
        http)
            log "Issuing Let's Encrypt certificate via HTTP-01 (DNS must already point here)"
            install -d -m 0755 /var/www/certbot
            ;;
        *)
            die "unknown TLS_MODE: $TLS_MODE"
            ;;
    esac

    local domain_args=()
    local d
    for d in $DOMAIN; do
        domain_args+=(-d "$d")
    done

    local certbot_args=(
        certonly --non-interactive --agree-tos --email "$EMAIL"
        "${domain_args[@]}"
    )
    if [ "$TLS_MODE" = "cloudflare" ]; then
        certbot_args+=(
            --dns-cloudflare
            --dns-cloudflare-credentials /etc/letsencrypt/cloudflare.ini
            --dns-cloudflare-propagation-seconds 30
        )
    else
        certbot_args+=(--webroot -w /var/www/certbot)
    fi

    if ! certbot "${certbot_args[@]}"; then
        warn "certificate issuance failed; nginx remains on HTTP. Fix DNS/token and re-run with --tls-only."
        return 0
    fi

    write_nginx_https
    log "TLS enabled for $DOMAIN"
}

configure_firewall() {
    log "Configuring UFW"
    ufw default deny incoming
    ufw default allow outgoing
    ufw allow "$SSH_PORT"/tcp comment 'SSH'
    ufw allow 80/tcp comment 'HTTP'
    ufw allow 443/tcp comment 'HTTPS'
    ufw deny 8080/tcp comment 'playground app is localhost-only'
    ufw --force enable
    ufw status verbose
}

configure_fail2ban() {
    log "Configuring fail2ban"
    cat > /etc/fail2ban/jail.d/chemical-sshd.local <<EOF
[DEFAULT]
backend = systemd
bantime = 1h
findtime = 10m
maxretry = 5
banaction = ufw
ignoreip = 127.0.0.1/8 ::1

[sshd]
enabled = true
port = $SSH_PORT
EOF
    chmod 0644 /etc/fail2ban/jail.d/chemical-sshd.local
    systemctl enable fail2ban
    systemctl restart fail2ban || warn "fail2ban failed to start; check: journalctl -u fail2ban"
}

configure_unattended_upgrades() {
    log "Configuring unattended security upgrades"
    cat > /etc/apt/apt.conf.d/20auto-upgrades <<'EOF'
APT::Periodic::Update-Package-Lists "1";
APT::Periodic::Unattended-Upgrade "1";
APT::Periodic::AutocleanInterval "7";
EOF
    cat > /etc/apt/apt.conf.d/51unattended-upgrades-chemical <<'EOF'
Unattended-Upgrade::Automatic-Reboot "false";
Unattended-Upgrade::Remove-Unused-Dependencies "true";
Unattended-Upgrade::Remove-Unused-Kernel-Packages "true";
EOF
    chmod 0644 /etc/apt/apt.conf.d/20auto-upgrades /etc/apt/apt.conf.d/51unattended-upgrades-chemical
    systemctl enable --now unattended-upgrades
}

configure_sysctl() {
    log "Applying kernel/network hardening"
    cat > /etc/sysctl.d/99-chemical-hardening.conf <<'EOF'
# Network
net.ipv4.conf.all.rp_filter = 1
net.ipv4.conf.default.rp_filter = 1
net.ipv4.tcp_syncookies = 1
net.ipv4.conf.all.accept_redirects = 0
net.ipv4.conf.default.accept_redirects = 0
net.ipv4.conf.all.send_redirects = 0
net.ipv4.conf.default.send_redirects = 0
net.ipv4.conf.all.accept_source_route = 0
net.ipv6.conf.all.accept_redirects = 0
net.ipv6.conf.all.accept_source_route = 0
net.ipv4.icmp_echo_ignore_broadcasts = 1
net.ipv4.conf.all.log_martians = 1

# Kernel
kernel.kptr_restrict = 2
kernel.dmesg_restrict = 1
kernel.yama.ptrace_scope = 1
fs.protected_hardlinks = 1
fs.protected_symlinks = 1
fs.protected_regular = 2
EOF
    chmod 0644 /etc/sysctl.d/99-chemical-hardening.conf
    sysctl --system >/dev/null || warn "some sysctl keys could not be applied"
}

configure_journald() {
    log "Limiting journald disk usage"
    install -d -m 0755 /etc/systemd/journald.conf.d
    cat > /etc/systemd/journald.conf.d/99-chemical.conf <<'EOF'
[Journal]
SystemMaxUse=500M
SystemKeepFree=1G
MaxRetentionSec=2week
Compress=yes
EOF
    chmod 0644 /etc/systemd/journald.conf.d/99-chemical.conf
    systemctl restart systemd-journald
}

harden_ssh() {
    log "Applying key-only SSH configuration"

    rm -f /run/chemical-ssh-ok
    install -d -m 0755 /etc/ssh/sshd_config.d
    cat > /etc/ssh/sshd_config.d/00-chemical-hardening.conf <<EOF
PermitRootLogin no
PasswordAuthentication no
KbdInteractiveAuthentication no
ChallengeResponseAuthentication no
PubkeyAuthentication yes
AuthorizedKeysFile .ssh/authorized_keys

AllowUsers $ADMIN_USER deploy

MaxAuthTries 3
LoginGraceTime 20
ClientAliveInterval 300
ClientAliveCountMax 2
X11Forwarding no
AllowAgentForwarding no
AllowTcpForwarding no
PermitTunnel no
PermitUserEnvironment no
UsePAM yes
EOF
    chmod 0644 /etc/ssh/sshd_config.d/00-chemical-hardening.conf

    if ! sshd -t; then
        rm -f /etc/ssh/sshd_config.d/00-chemical-hardening.conf
        die "sshd configuration test failed; hardening was not applied"
    fi

    local effective_password effective_root
    effective_password="$(sshd -T 2>/dev/null | awk '$1=="passwordauthentication"{print $2; exit}')"
    effective_root="$(sshd -T 2>/dev/null | awk '$1=="permitrootlogin"{print $2; exit}')"
    if [ "$effective_password" != "no" ] || [ "$effective_root" != "no" ]; then
        warn "sshd effective config is not fully hardened (PasswordAuthentication=$effective_password, PermitRootLogin=$effective_root); inspect /etc/ssh/sshd_config.d/"
    fi

    cat > /usr/local/sbin/chemical-ssh-rollback <<'EOF'
#!/bin/sh
set -eu
if [ -f /run/chemical-ssh-ok ]; then
    exit 0
fi
rm -f /etc/ssh/sshd_config.d/00-chemical-hardening.conf
sshd -t
systemctl reload ssh
EOF
    chmod 0755 /usr/local/sbin/chemical-ssh-rollback

    # Safety net: if the local side cannot verify key login, password auth is
    # restored automatically after 10 minutes.
    if command -v systemd-run >/dev/null 2>&1; then
        systemctl stop chemical-ssh-rollback.timer >/dev/null 2>&1 || true
        if ! systemd-run --unit=chemical-ssh-rollback --on-active=10min --collect \
            /usr/local/sbin/chemical-ssh-rollback; then
            warn "could not schedule the SSH rollback timer; keep the provider console available"
        fi
    fi

    systemctl reload ssh
    log "SSH hardening applied (rollback timer armed for 10 minutes)"
}

provision() {
    log "Checking operating system"
    if [ -r /etc/os-release ]; then
        # shellcheck disable=SC1091
        . /etc/os-release
        log "Detected ${PRETTY_NAME:-unknown OS}"
        if [ "${ID:-}" != "ubuntu" ] || [ "${VERSION_ID:-}" != "24.04" ]; then
            warn "this script targets Ubuntu 24.04; continuing on ${ID:-unknown} ${VERSION_ID:-unknown}"
        fi
    fi
    [ "$(uname -m)" = "x86_64" ] || die "the published playground binary is linux-x64; this host is $(uname -m)"

    export DEBIAN_FRONTEND=noninteractive
    export NEEDRESTART_MODE=l

    log "Updating packages"
    apt-get update
    apt-get -y -o Dpkg::Options::=--force-confold upgrade

    log "Installing baseline packages"
    apt-get -y -o Dpkg::Options::=--force-confold install \
        sudo curl ca-certificates gnupg lsb-release file acl \
        ufw fail2ban unattended-upgrades \
        nginx certbot python3-certbot-nginx \
        systemd-timesyncd

    if ! command -v docker >/dev/null 2>&1; then
        log "Installing Docker"
        apt-get -y -o Dpkg::Options::=--force-confold install docker.io
    else
        log "Docker is already installed; keeping the existing installation"
    fi

    systemctl enable --now systemd-timesyncd || true

    log "Creating service users and directories"
    ensure_app_user
    ensure_admin_user
    harden_app_user
    ensure_deploy_user

    log "Configuring Docker"
    configure_docker

    log "Configuring nginx (HTTP)"
    write_nginx_http

    log "Configuring firewall"
    configure_firewall

    configure_fail2ban
    configure_unattended_upgrades
    configure_sysctl
    configure_journald
    write_app_scripts
    write_systemd_units

    # The app unit is enabled but not started here; the local setup script
    # uploads the binary and starts it, so a fresh server never runs a
    # half-installed service.
    if [ "$TLS_MODE" = "cloudflare" ]; then
        issue_certificate
    elif [ "$TLS_MODE" = "http" ]; then
        issue_certificate
    else
        log "Skipping TLS issuance (TLS_MODE=$TLS_MODE)"
    fi

    if [ -f /var/run/reboot-required ]; then
        warn "a reboot is required to finish applying updates: $(tr '\n' ' ' </var/run/reboot-required)"
    fi

    log "Provisioning complete"
    printf 'APP_USER=%s\nAPP_GROUP=%s\nAPP_DIR=%s\nAPEX=%s\n' \
        "$APP_USER" "$APP_GROUP" "$APP_DIR" "$APEX" > /run/chemical-playground-setup.env
    chmod 0644 /run/chemical-playground-setup.env
}

case "$PHASE" in
    provision)
        provision
        ;;
    harden)
        harden_ssh
        ;;
    tls)
        issue_certificate
        ;;
    *)
        die "unknown phase: $PHASE"
        ;;
esac
